// Calendar — the third app on its own origin (web-app-suite.md Wave 2, run B). Everything the apex
// knows about it: origin, gateway allowlist, route, Apps-section entry. Generated by
// scripts/new-web-app.sh; adding this file IS the registration (`registry/index.ts` globs `apps/*.ts`).
import type { ProxyMethodAllowlist } from '@tenshu/sdk/bridge'
import { appOrigin, SESSION_METHODS, V1_INSTALL_AT_MS, type HostedApp } from '../types'

declare global {
  interface ImportMetaEnv {
    /** The Calendar app's origin (see `apps/registry/apps/calendar.ts`). */
    readonly VITE_CALENDAR_ORIGIN?: string
  }
}

// ⚠⚠ F5 — exactly the methods `web/calendar` calls: its `ProxyMethod` table in
// `web/calendar/src/lib/proxy.ts` (`gatewayPermissions.test.ts` fails on drift either way). Exact
// names only; a `.*` prefix only for a namespace this app owns outright, and never a bare `'*'`.
// ⚠ Exact names, not `calendar.*`: a prefix would also grant `calendar.reminder.dismiss` /
// `.snooze`, which the web never calls (nothing in a tab fires a reminder — calendar-app.md §Web
// scope W1), and every `calendar.*` handler added later.
// ⚠ Nothing of Drive's or Contacts': no `fs.*`, no `contact.*`.
const METHODS: ProxyMethodAllowlist = [
  ...SESSION_METHODS,
  'sync.health.observe',
  'calendar.list',
  'calendar.list.observe',
  'calendar.occurrences',
  'calendar.occurrences.observe',
  'calendar.hidden.observe',
  'calendar.setVisible',
  'calendar.default',
  'calendar.default.observe',
  'calendar.setDefault',
  'calendar.save',
  'calendar.delete',
  'calendar.event.save',
  'calendar.occurrence.save',
  'calendar.event.delete',
  'calendar.occurrence.delete',
  'calendar.subscriptions',
  'calendar.subscriptions.observe',
  'calendar.subscription.add',
  'calendar.subscription.setEnabled',
  'calendar.subscription.remove',
  'calendar.importIcs',
  'calendar.exportIcs',
  'calendar.reminders',
  'calendar.setReminders',
  'calendar.defaultReminderMinutes',
]

const PROD_ORIGIN = 'https://calendar.tenshu.app'

export const calendar: HostedApp = {
  id: 'calendar',
  order: 30,
  title: 'Calendar',
  prodOrigin: PROD_ORIGIN,
  envName: 'VITE_CALENDAR_ORIGIN',
  devPort: 5176,
  origin: () => appOrigin(import.meta.env.VITE_CALENDAR_ORIGIN, PROD_ORIGIN, 5176),
  methods: METHODS,
  routePath: 'calendar/*',
  // ⚠ DISPLAY data for the Apps section — what the app can actually call is `methods` above.
  manifest: {
    id: 'calendar',
    label: 'Calendar',
    description: 'Your calendars, end-to-end encrypted.',
    version: '0.1.0',
    installedAtMs: V1_INSTALL_AT_MS,
    launchPath: '/calendar',
    // ⚠ The permissions listed here are DISPLAY data, like Drive's — what the app can actually call
    // is `methods` above (F5).
    permissions: [
      {
        id: 'calendar.read',
        label: 'Read your calendars',
        description: 'See your calendars, their events and the feeds you subscribe to.',
        state: 'granted',
        lastUsedAtMs: null,
      },
      {
        id: 'calendar.write',
        label: 'Manage your calendars',
        description: 'Add, edit and delete calendars and events, import and export .ics files, and add or remove subscriptions.',
        state: 'granted',
        lastUsedAtMs: null,
      },
    ],
    services: [
      {
        id: 'calendar',
        label: 'CalendarService',
        reason: 'Stores your calendars, events, reminder times and subscriptions, encrypted client-side.',
      },
      {
        id: 'preference',
        label: 'PreferenceService',
        reason: 'Keeps your default calendar, and which calendars this browser hides.',
      },
    ],
  },
}

export default calendar
